const allItems = $input.all();
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

let total = 0;
let bugs = 0;
let tasks = 0;
let features = 0;
let needsTriage = 0;
let closed = 0;
const authorCounts = {};

for (const item of allItems) {
  const issue = item.json;
  // Исключаем пулл-реквесты
  if (issue.pull_request) continue;

  const createdAt = new Date(issue.created_at);
  if (createdAt >= oneWeekAgo || issue.state === 'open') {
    total++;
    if (issue.state === 'closed') closed++;

    const author = issue.user ? issue.user.login : 'unknown';
    authorCounts[author] = (authorCounts[author] || 0) + 1;

    const labelNames = (issue.labels || []).map(l => (l.name || '').toLowerCase());
    if (labelNames.includes('bug')) bugs++;
    if (labelNames.includes('task')) tasks++;
    if (labelNames.includes('feature-request') || labelNames.includes('feature')) features++;
    if (labelNames.includes('needs-triage')) needsTriage++;
  }
}

// Форматируем авторов в читаемую строку
const authorSummary = Object.entries(authorCounts)
  .map(([author, count]) => `${author} (${count})`)
  .join(', ') || 'нет активности';

return [{
  json: {
    total,
    bugs,
    tasks,
    features,
    needsTriage,
    closed,
    authorSummary,
    reportDate: new Date().toLocaleDateString('ru-RU')
  }
}];

const current = $('Group Stats by Type & Author').first().json;
const rows = $input.all().map(r => r.json).filter(r => r.total !== undefined);

// Берём последнюю сохранённую неделю (если есть)
const prev = rows.length > 0 ? rows[rows.length - 1] : {
  total: 0,
  bugs: 0,
  tasks: 0,
  features: 0,
  needsTriage: 0
};

function formatDelta(currVal, prevVal) {
  const diff = Number(currVal || 0) - Number(prevVal || 0);
  if (diff > 0) return `+${diff}`;
  if (diff < 0) return `${diff}`;
  return '0 (без изм.)';
}

return [{
  json: {
    ...current,
    prev_total: prev.total || 0,
    prev_bugs: prev.bugs || 0,
    prev_tasks: prev.tasks || 0,
    prev_features: prev.features || 0,
    prev_needsTriage: prev.needsTriage || 0,
    delta_total: formatDelta(current.total, prev.total),
    delta_bugs: formatDelta(current.bugs, prev.bugs),
    delta_tasks: formatDelta(current.tasks, prev.tasks),
    delta_features: formatDelta(current.features, prev.features),
    delta_needsTriage: formatDelta(current.needsTriage, prev.needsTriage)
  }
}];

